/**
 * Guidance state machine — pure computation, no React dependencies.
 *
 * Core types and helper functions for confidence-gated turn-by-turn navigation.
 * Drives the live guidance UI overlay and reroute logic.
 */

import type { DirectionStep, NormalizedNodeRecord } from '../domain/navGraph';
import type { PathResult } from '../domain/navGraph';
import type { RouteSessionReadyState } from './routeSessionState';
import type { NormalizedPoint } from '../../src/shared/gps';

// ============================================================
// Core types
// ============================================================

/**
 * GPS and heading confidence classification.
 *
 * Used by `deriveConfidence` to determine how aggressively
 * the guidance engine trusts the current position fix.
 */
export type ConfidenceLevel = 'high' | 'medium' | 'low' | 'none';

/**
 * Phase of the guidance state machine.
 *
 * State transitions are governed by `deriveNextPhase`:
 * - `idle`          → Initial state; no route loaded
 * - `low-confidence` → Route loaded, but GPS/heading signal is weak
 * - `guiding`       → Route active with confident position; advancing steps
 * - `rerouting`     → Off-route detected, computing new path
 * - `arrived`        → User has reached the destination
 */
export type GuidancePhase =
  | 'idle'
  | 'low-confidence'
  | 'guiding'
  | 'rerouting'
  | 'arrived';

/**
 * Core guidance state for live navigation.
 *
 * Carries the route, current position, and confidence signals needed
 * to drive step advancement and reroute decisions.
 */
export interface GuidanceState {
  phase: GuidancePhase;
  /** The route being followed — must be in 'ready' phase. */
  route: RouteSessionReadyState;
  /** Index of the active DirectionStep (0-based). */
  currentStepIndex: number;
  /** User's current position in normalized [0,1] map space. */
  snappedPosition: NormalizedPoint;
  /** Nearest walkable node ID to the snapped position. */
  snappedNodeId: string;
  /** Device compass heading in degrees (0–360), null if unavailable. */
  heading: number | null;
  /** Heading accuracy in degrees, null if unavailable. */
  headingConfidence: number | null;
  /** Classification of current position fix quality. */
  positionConfidence: ConfidenceLevel;
  /** Unix timestamp (ms) of the last position fix. */
  lastFixTimestamp: number;
  /** Unix timestamp (ms) when off-route was first detected, null if on-route. */
  offRouteDetectedAt: number | null;
  /** Consecutive fixes where off-route was detected. */
  offRouteFixCount: number;
  /** Result of the last reroute computation, null if no reroute has been attempted. */
  rerouteResult: PathResult | null;
}

// ============================================================
// Helper function input types
// ============================================================

export interface PositionFix {
  readonly isConfident: boolean;
  readonly accuracyMeters: number | null;
}

export interface HeadingFix {
  readonly headingDegrees: number | null;
  readonly accuracyDegrees: number | null;
}

// ============================================================
// Pure helper functions
// ============================================================

/**
 * Derive the GPS/heading confidence level from position and heading fixes.
 *
 * Confidence levels:
 * - `high`:   GPS fix is confident AND heading accuracy ≤ 15°
 * - `medium`: GPS fix is confident but heading is missing or unreliable (> 15°)
 * - `low`:    GPS fix not confident but finite (accuracy exists)
 * - `none`:   No GPS fix or infinite accuracy
 */
export function deriveConfidence(
  positionFix: PositionFix,
  headingFix: HeadingFix,
): ConfidenceLevel {
  // none: no GPS fix (null) or infinite accuracy
  if (positionFix.accuracyMeters == null || !Number.isFinite(positionFix.accuracyMeters)) {
    return 'none';
  }

  // low: GPS fix not confident but finite (accuracy exists but > threshold)
  if (!positionFix.isConfident) {
    return 'low';
  }

  // medium: GPS confident but heading missing or unreliable
  if (
    headingFix.headingDegrees == null
    || headingFix.accuracyDegrees == null
    || !Number.isFinite(headingFix.accuracyDegrees)
    || headingFix.accuracyDegrees > 15
  ) {
    return 'medium';
  }

  // high: GPS confident AND heading reliable (≤ 15°)
  return 'high';
}

// ============================================================
// Private helpers
// ============================================================

/**
 * Build an ordered coordinate lookup from a path and its route state.
 * Looks for a nodeById map on the path (production) or falls back to
 * extracting coordinates directly from the node IDs using route.path.nodeById.
 *
 * The path may carry nodeById as an extended property (production path),
 * or the coordinates are resolved via route.path.nodeById (test path).
 */
function buildCoordLookup(
  path: PathResult,
  route: RouteSessionReadyState,
): Map<number, { x: number; y: number }> {
  const coords = new Map<number, { x: number; y: number }>();

  // Try path.nodeById first (production extension pattern)
  const pathAsExtended = path as PathResult & { nodeById?: Map<string, NormalizedNodeRecord> };
  if (pathAsExtended.nodeById && typeof pathAsExtended.nodeById.get === 'function') {
    const nodeById = pathAsExtended.nodeById;
    for (let i = 0; i < path.nodeIds.length; i++) {
      const record = nodeById.get(path.nodeIds[i]);
      if (record) {
        coords.set(i, { x: record.node.x, y: record.node.y });
      }
    }
    return coords;
  }

  // Fallback: resolve via route.path.nodeById (test / production NormalizedNavGraph pattern)
  const routePathAsGraph = route.path as PathResult & { nodeById?: Map<string, NormalizedNodeRecord> };
  const nodeById = routePathAsGraph.nodeById;
  if (nodeById && typeof nodeById.get === 'function') {
    for (let i = 0; i < path.nodeIds.length; i++) {
      const record = nodeById.get(path.nodeIds[i]);
      if (record) {
        coords.set(i, { x: record.node.x, y: record.node.y });
      }
    }
  }

  return coords;
}

/**
 * Compute perpendicular (orthogonal) distance from a point to a line segment.
 *
 * Returns the minimum distance from `point` to any point on the segment
 * between `segStart` and `segEnd`.
 *
 * Uses the standard point-to-segment formula:
 * Let t = dot(P - segStart, segEnd - segStart) / |segEnd - segStart|²
 * Clamp t to [0, 1] (to stay on the segment)
 * Closest point = segStart + t * (segEnd - segStart)
 * Distance = |P - closest_point|
 */
function pointToSegmentDistance(
  point: NormalizedPoint,
  segStart: { x: number; y: number },
  segEnd: { x: number; y: number },
): number {
  const dx = segEnd.x - segStart.x;
  const dy = segEnd.y - segStart.y;
  const lenSq = dx * dx + dy * dy;

  // Degenerate segment (start === end): return distance to the point
  if (lenSq === 0) {
    return Math.sqrt((point.x - segStart.x) ** 2 + (point.y - segStart.y) ** 2);
  }

  // Parameter t for the projection of P onto the segment line
  const t = Math.max(
    0,
    Math.min(
      1,
      ((point.x - segStart.x) * dx + (point.y - segStart.y) * dy) / lenSq,
    ),
  );

  const closestX = segStart.x + t * dx;
  const closestY = segStart.y + t * dy;

  return Math.sqrt((point.x - closestX) ** 2 + (point.y - closestY) ** 2);
}

// ============================================================
// Public route-geometry helpers
// ============================================================

/**
 * Returns true when the user's position is off the active route segment.
 *
 * Detects deviation by measuring perpendicular distance from the current
 * position to the current path segment (from path.nodeIds[currentStepIndex]
 * to path.nodeIds[currentStepIndex + 1]).
 *
 * @param position     User's current snapped position
 * @param currentStepIndex  Which step in the route is active
 * @param path         The current route path
 * @param route        The route session state (provides normalized graph nodeById)
 * @param threshold    Deviation threshold in normalized units (default: 0.05)
 */
export function isOffRoute(
  position: NormalizedPoint,
  currentStepIndex: number,
  path: PathResult,
  route: RouteSessionReadyState,
  threshold = 0.05,
): boolean {
  if (!path.found || path.nodeIds.length < 2) return false;

  const coords = buildCoordLookup(path, route);

  // When at or beyond the last segment, use distance to the final node
  if (currentStepIndex >= path.nodeIds.length - 1) {
    const lastNode = coords.get(path.nodeIds.length - 1);
    if (!lastNode) return false;

    const dist = Math.sqrt(
      (position.x - lastNode.x) ** 2 + (position.y - lastNode.y) ** 2,
    );
    return dist > threshold;
  }

  const startNode = coords.get(currentStepIndex);
  const endNode = coords.get(currentStepIndex + 1);
  if (!startNode || !endNode) return false;

  const distance = pointToSegmentDistance(position, startNode, endNode);
  return distance > threshold;
}

/**
 * Returns true when the user has reached the waypoint at the start of the next step.
 *
 * Uses the same perpendicular-distance approach as `isOffRoute` but with a
 * smaller threshold so that near-passing doesn't trigger an advance mid-segment.
 *
 * @param position        User's current snapped position
 * @param currentStepIndex  Index of the current step (advance check goes to step + 1)
 * @param path            The current route path
 * @param route           The route session state (provides normalized graph nodeById)
 * @param advanceThreshold  Proximity threshold for triggering advance (default: 0.03)
 */
export function shouldAdvanceStep(
  position: NormalizedPoint,
  currentStepIndex: number,
  path: PathResult,
  route: RouteSessionReadyState,
  advanceThreshold = 0.03,
): boolean {
  if (!path.found || path.nodeIds.length < 2) return false;

  const coords = buildCoordLookup(path, route);

  // If the next step index is beyond the node list, use the last node
  const nextStepIdx = currentStepIndex + 1;
  if (nextStepIdx >= path.nodeIds.length) {
    const lastNode = coords.get(path.nodeIds.length - 1);
    if (!lastNode) return false;
    return (
      Math.sqrt(
        (position.x - lastNode.x) ** 2 + (position.y - lastNode.y) ** 2,
      ) <= advanceThreshold
    );
  }

  const startNode = coords.get(currentStepIndex);
  const endNode = coords.get(nextStepIdx);
  if (!startNode || !endNode) return false;

  const distance = pointToSegmentDistance(position, startNode, endNode);
  return distance <= advanceThreshold;
}

/**
 * Derive the next phase from current state and signals.
 *
 * Phase transition rules:
 * - `idle`          → `isConfident` ? 'guiding' : 'low-confidence'
 * - `low-confidence` → `isConfident` ? 'guiding' : stay 'low-confidence'
 * - `guiding`       → `hasArrived` ? 'arrived'
 *                    → `offRouteFixCount >= rerouteConfirmFixes` ? 'rerouting'
 *                    → stay 'guiding'
 * - `rerouting`     → always transitions to 'guiding' (assumes reroute succeeded)
 * - `arrived`       → stays 'arrived'
 *
 * @param state                  Current guidance state
 * @param isConfident            Whether current position is high or medium confidence
 * @param hasArrived             Whether the user has arrived at the destination
 * @param offRouteFixCount       Number of consecutive off-route position fixes
 * @param rerouteConfirmFixes    Fixes required before triggering reroute (default: 3)
 */
export function deriveNextPhase(
  state: GuidanceState,
  isConfident: boolean,
  hasArrived: boolean,
  offRouteFixCount: number,
  rerouteConfirmFixes = 3,
): GuidancePhase {
  switch (state.phase) {
    case 'idle':
      return isConfident ? 'guiding' : 'low-confidence';

    case 'low-confidence':
      return isConfident ? 'guiding' : 'low-confidence';

    case 'guiding':
      if (hasArrived) return 'arrived';
      if (offRouteFixCount >= rerouteConfirmFixes) return 'rerouting';
      return 'guiding';

    case 'rerouting':
      // Assumes the caller has set rerouteResult; transitions back to guiding
      return 'guiding';

    case 'arrived':
      return 'arrived';
  }
}

/**
 * Return the active DirectionStep for the current step index.
 *
 * Returns null when there is no active route, no directions have been generated,
 * or the current step index is out of bounds.
 */
export function getActiveStep(state: GuidanceState): DirectionStep | null {
  const { route, currentStepIndex } = state;
  if (route.phase !== 'ready') return null;
  if (!route.directions) return null;
  const { steps } = route.directions;
  if (currentStepIndex < 0 || currentStepIndex >= steps.length) return null;
  return steps[currentStepIndex] ?? null;
}

/**
 * GPS + heading subscription hook.
 *
 * Wraps navigator.geolocation.watchPosition and an optional magnetometer reader
 * behind thin interfaces so both are injectable for unit testing.
 *
 * Returns:
 * - position: latest GPS fix (null until first reading)
 * - heading: raw magnetometer reading (null until available)
 * - smoothedHeadingDegrees: EMA-smoothed heading (0–360, null until first reading)
 * - isConfident: true when accuracy ≤ maxAccuracyMeters (from isGpsFixConfident)
 * - isHeadingValid: true when magnetometer is available AND accuracyDegrees ≤ 15
 */

import { useEffect, useRef, useState } from 'react';
import { isGpsFixConfident } from '../../src/shared/gps';

/* ──────────────── Types ──────────────── */

/**
 * A single GPS position fix.
 * headingDegrees may be null when the device does not provide it.
 */
export interface PositionFix {
  latitude: number;
  longitude: number;
  accuracyMeters: number;
  headingDegrees: number | null;
  timestamp: number;
}

/**
 * A single magnetometer/compass reading.
 * headingDegrees is 0–360 clockwise from magnetic north.
 * accuracyDegrees estimates heading precision.
 */
export interface HeadingData {
  headingDegrees: number;
  accuracyDegrees: number;
}

/**
 * Abstracts the device magnetometer / compass API.
 * Start/stop lifecycle so the hook controls when the sensor is active.
 */
export interface HeadingReader {
  start(callback: (data: HeadingData) => void): void;
  stop(): void;
}

/**
 * Abstracts navigator.geolocation.watchPosition.
 * Returns a stop handle so the hook can tear down the watcher on unmount.
 */
export interface PositionReader {
  watchPosition(
    onPosition: (fix: PositionFix) => void,
    onError: (error: Error) => void,
  ): { stop: () => void };
}

/* ──────────────── Hook options ──────────────── */

export interface UseCurrentPositionOptions {
  /** Minimum interval between position updates in ms. Default: 2000. */
  updateIntervalMs?: number;
  /** Maximum accuracy (metres) for isConfident. Default: 50. */
  maxAccuracyMeters?: number;
  /** Heading source. Defaults to DefaultNativeHeadingReader. */
  headingReader?: HeadingReader;
  /** Position source. Defaults to DefaultPositionReader. */
  positionReader?: PositionReader;
}

/* ──────────────── Default readers ──────────────── */

/**
 * Default heading reader using the expo-sensors Magnetometer API.
 * Falls back to a no-op if the module is unavailable (e.g. web / no sensor).
 * Maps magnetometer X/Y magnitude to a heading in degrees.
 */
export class DefaultNativeHeadingReader implements HeadingReader {
  private subscription: { remove: () => void } | null = null;

  start(callback: (data: HeadingData) => void): void {
    this.stop();
    try {
      // Dynamic import so this file still compiles without expo-sensors installed.
      // eslint-disable-next-line @typescript-eslint/no-var-requires
      const { Magnetometer } = require('expo-sensors') as {
        Magnetometer: { addListener: (cb: (e: { x: number; y: number }) => void) => { remove: () => void } };
      };
      this.subscription = Magnetometer.addListener((event) => {
        // atan2(y, x) gives angle from magnetic north in radians; + math.PI/2 rotates
        // so 0° points magnetic north, then convert to degrees and normalise 0–360.
        const radians = Math.atan2(event.x, event.y);
        let degrees = ((radians * 180) / Math.PI + 90 + 360) % 360;
        callback({ headingDegrees: degrees, accuracyDegrees: 10 });
      });
    } catch {
      // expo-sensors not available — heading stays null.
    }
  }

  stop(): void {
    this.subscription?.remove();
    this.subscription = null;
  }
}

/**
 * Default position reader using navigator.geolocation.watchPosition.
 * Works in any browser or React Native environment with the Geolocation API.
 */
export class DefaultPositionReader implements PositionReader {
  watchPosition(
    onPosition: (fix: PositionFix) => void,
    onError: (error: Error) => void,
  ): { stop: () => void } {
    let watchId: number;

    const onGeoSuccess = (pos: GeolocationPosition) => {
      onPosition({
        latitude: pos.coords.latitude,
        longitude: pos.coords.longitude,
        accuracyMeters: pos.coords.accuracy ?? Infinity,
        headingDegrees: pos.coords.heading ?? null,
        timestamp: pos.timestamp,
      });
    };

    const onGeoError = (err: GeolocationPositionError) => {
      onError(new Error(`[Geolocation] ${err.message}`));
    };

    watchId = navigator.geolocation.watchPosition(onGeoSuccess, onGeoError, {
      enableHighAccuracy: true,
    });

    return {
      stop() {
        navigator.geolocation.clearWatch(watchId);
      },
    };
  }
}

/* ──────────────── Hook ──────────────── */

export interface UseCurrentPositionReturn {
  position: PositionFix | null;
  heading: HeadingData | null;
  /** EMA-smoothed heading in degrees (0–360). Null until first reading. */
  smoothedHeadingDegrees: number | null;
  isConfident: boolean;
  isHeadingValid: boolean;
}

/**
 * EMA smoothing factor applied per heading update.
 * Higher alpha → faster convergence to new reading.
 */
const HEADING_EMA_ALPHA = 0.3;

/**
 * Maximum magnetometer accuracy (degrees) to trust the heading.
 * Readings with worse accuracy are treated as invalid.
 */
const HEADING_ACCURACY_THRESHOLD_DEG = 15;

/**
 * Subscribes to device position and (optionally) magnetometer heading.
 *
 * Heading EMA handles wraparound at 0°/360° by always moving through the
 * shorter angular path toward the new reading.
 */
export function useCurrentPosition(
  options: UseCurrentPositionOptions = {},
): UseCurrentPositionReturn {
  const {
    maxAccuracyMeters = 50,
    headingReader = new DefaultNativeHeadingReader(),
    positionReader = new DefaultPositionReader(),
  } = options;

  const [position, setPosition] = useState<PositionFix | null>(null);
  const [heading, setHeading] = useState<HeadingData | null>(null);
  const [smoothedHeadingDegrees, setSmoothedHeadingDegrees] = useState<number | null>(null);
  const [isHeadingValid, setIsHeadingValid] = useState(false);

  // Keep the current smoothed heading in a ref so we don't need to re-subscribe
  // on every EMA update.
  const smoothedHeadingRef = useRef<number | null>(null);

  // True once at least one position fix has been received.
  const hasPosition = useRef(false);

  useEffect(() => {
    // ── Position subscription ────────────────────────────────────────────────
    const posHandle = positionReader.watchPosition(
      (fix) => {
        hasPosition.current = true;
        setPosition(fix);
      },
      // Non-fatal: keep the last known position rather than resetting to null.
      () => {},
    );

    // ── Heading subscription ────────────────────────────────────────────────
    headingReader.start((data) => {
      setHeading(data);
      const isValid = data.accuracyDegrees <= HEADING_ACCURACY_THRESHOLD_DEG;
      setIsHeadingValid(isValid);

      if (!isValid) return;

      const raw = data.headingDegrees;
      const current = smoothedHeadingRef.current;

      if (current === null) {
        // First valid reading — no smoothing needed.
        smoothedHeadingRef.current = raw;
        setSmoothedHeadingDegrees(raw);
        return;
      }

      // Compute shortest angular distance from current to new reading.
      let delta = raw - current;
      if (delta > 180) delta -= 360;
      if (delta < -180) delta += 360;

      const smoothed = current + HEADING_EMA_ALPHA * delta;
      // Normalise to 0–360.
      const normalised = ((smoothed % 360) + 360) % 360;

      smoothedHeadingRef.current = normalised;
      setSmoothedHeadingDegrees(normalised);
    });

    return () => {
      posHandle.stop();
      headingReader.stop();
    };
  }, [positionReader, headingReader]); // stable object references — no re-mount on render

  const isConfident = hasPosition.current
    ? position !== null && isGpsFixConfident(position.accuracyMeters, maxAccuracyMeters)
    : false;

  return {
    position,
    heading,
    smoothedHeadingDegrees,
    isConfident,
    isHeadingValid,
  };
}

/**
 * MobilePathfindingEngine — custom A* pathfinding on NormalizedNavGraph.
 *
 * Avoids the ngraph.graph dependency by implementing A* directly using
 * the normalized graph structure produced by normalizeNavGraph().
 *
 * Features:
 * - Dual-mode routing: standard vs accessible
 * - Inter-floor traversal via stairs/elevator/ramp connectors
 * - Euclidean heuristic with floor-level penalty
 * - Explicit result types (no exceptions for not-found)
 */

import type { NavFloor, NavNode } from '../../src/shared/types';
import type {
  DirectionStep,
  DirectionsResult,
  NormalizedEdgeRecord,
  NormalizedNavGraph,
  NormalizedNodeRecord,
  PathResult,
  PathSegment,
  RouteMode,
  StepIcon,
} from '../domain/navGraph';

// ============================================================
// Priority Queue (binary heap)
// ============================================================

interface QueueEntry {
  nodeId: string;
  gScore: number;
  fScore: number;
}

/**
 * Min-heap priority queue for A* frontier.
 */
class PriorityQueue {
  private heap: QueueEntry[] = [];

  push(nodeId: string, gScore: number, fScore: number): void {
    this.heap.push({ nodeId, gScore, fScore });
    this.bubbleUp(this.heap.length - 1);
  }

  pop(): QueueEntry | undefined {
    if (this.heap.length === 0) return undefined;
    const min = this.heap[0];
    const last = this.heap.pop()!;
    if (this.heap.length > 0) {
      this.heap[0] = last;
      this.bubbleDown(0);
    }
    return min;
  }

  isEmpty(): boolean {
    return this.heap.length === 0;
  }

  private bubbleUp(index: number): void {
    while (index > 0) {
      const parent = Math.floor((index - 1) / 2);
      if (this.heap[parent].fScore <= this.heap[index].fScore) break;
      [this.heap[parent], this.heap[index]] = [this.heap[index], this.heap[parent]];
      index = parent;
    }
  }

  private bubbleDown(index: number): void {
    const length = this.heap.length;
    while (true) {
      const left = 2 * index + 1;
      const right = 2 * index + 2;
      let smallest = index;

      if (left < length && this.heap[left].fScore < this.heap[smallest].fScore) {
        smallest = left;
      }
      if (right < length && this.heap[right].fScore < this.heap[smallest].fScore) {
        smallest = right;
      }
      if (smallest === index) break;
      [this.heap[smallest], this.heap[index]] = [this.heap[index], this.heap[smallest]];
      index = smallest;
    }
  }
}

// ============================================================
// Constants
// ============================================================

/** Weight for inter-floor traversal in standard mode (elevator/ramp) */
const INTER_FLOOR_STANDARD_WEIGHT = 0.3;
/** Weight for inter-floor traversal via elevator in accessible mode */
const INTER_FLOOR_ELEVATOR_WEIGHT = 0.45;
/** Weight for inter-floor traversal via ramp in accessible mode */
const INTER_FLOOR_RAMP_WEIGHT = 0.45;
/** Stairs are not accessible — used as sentinel for inaccessible inter-floor traversal */
const INTER_FLOOR_STAIRS_INACCESSIBLE = Infinity;
/** Penalty multiplier for floor-level difference in heuristic */
const FLOOR_PENALTY_PER_LEVEL = 0.5;

// ============================================================
// Engine
// ============================================================

/**
 * Custom A* pathfinding engine for mobile.
 *
 * Operates directly on NormalizedNavGraph, avoiding ngraph.graph dependency.
 */
export class MobilePathfindingEngine {
  private readonly graph: NormalizedNavGraph;

  constructor(graph: NormalizedNavGraph) {
    this.graph = graph;
  }

  /**
   * Find a route between two nodes.
   *
   * @param fromId - Source node ID
   * @param toId - Destination node ID
   * @param mode - 'standard' or 'accessible'
   * @returns PathResult with found status, ordered nodeIds, segments, and totalDistance
   */
  findRoute(fromId: string, toId: string, mode: RouteMode): PathResult {
    // Trivial same-node case
    if (fromId === toId) {
      return { found: true, nodeIds: [fromId], totalDistance: 0, segments: [] };
    }

    // Node existence guards
    if (!this.graph.nodeById.has(fromId) || !this.graph.nodeById.has(toId)) {
      return { found: false, nodeIds: [], totalDistance: 0, segments: [] };
    }

    const { nodeIds, segments, totalDistance } = this.astar(fromId, toId, mode);

    if (nodeIds.length === 0) {
      return { found: false, nodeIds: [], totalDistance: 0, segments: [] };
    }

    return { found: true, nodeIds, totalDistance, segments };
  }

  /**
   * A* search implementation.
   */
  private astar(
    startId: string,
    goalId: string,
    mode: RouteMode,
  ): { nodeIds: string[]; segments: PathSegment[]; totalDistance: number } {
    const frontier = new PriorityQueue();
    const cameFrom = new Map<string, { nodeId: string; edge: NormalizedEdgeRecord }>();
    const gScore = new Map<string, number>();
    const visited = new Set<string>();

    const startRecord = this.graph.nodeById.get(startId)!;
    const goalRecord = this.graph.nodeById.get(goalId)!;

    const startHeuristic = this.heuristic(startRecord, goalRecord);
    frontier.push(startId, 0, startHeuristic);
    gScore.set(startId, 0);

    while (!frontier.isEmpty()) {
      const current = frontier.pop()!;
      const currentId = current.nodeId;

      // Goal reached — reconstruct path
      if (currentId === goalId) {
        return this.reconstructPath(startId, goalId, cameFrom, mode);
      }

      if (visited.has(currentId)) continue;
      visited.add(currentId);

      const neighbors = this.getNeighbors(currentId, mode);

      for (const { neighborId, edgeRecord, edgeWeight } of neighbors) {
        if (visited.has(neighborId)) continue;

        const tentativeG = (gScore.get(currentId) ?? Infinity) + edgeWeight;

        if (tentativeG < (gScore.get(neighborId) ?? Infinity)) {
          gScore.set(neighborId, tentativeG);
          cameFrom.set(neighborId, { nodeId: currentId, edge: edgeRecord });

          const neighborRecord = this.graph.nodeById.get(neighborId)!;
          const f = tentativeG + this.heuristic(neighborRecord, goalRecord);
          frontier.push(neighborId, tentativeG, f);
        }
      }
    }

    // No path found
    return { nodeIds: [], segments: [], totalDistance: 0 };
  }

  /**
   * Reconstruct path from A* search results.
   */
  private reconstructPath(
    startId: string,
    goalId: string,
    cameFrom: Map<string, { nodeId: string; edge: NormalizedEdgeRecord }>,
    mode: RouteMode,
  ): { nodeIds: string[]; segments: PathSegment[]; totalDistance: number } {
    const nodeIds: string[] = [];
    const segments: PathSegment[] = [];
    let currentId: string | undefined = goalId;
    let totalDistance = 0;

    while (currentId !== undefined) {
      nodeIds.unshift(currentId);

      const prev = cameFrom.get(currentId);
      if (prev === undefined) break;

      const { nodeId: prevId, edge } = prev;
      const distance =
        mode === 'accessible' ? edge.effectiveAccessibleWeight : edge.edge.standardWeight;

      segments.unshift({ fromId: prevId, toId: currentId, distance });
      totalDistance += distance;

      currentId = prevId;
    }

    nodeIds.unshift(startId);
    return { nodeIds, segments, totalDistance };
  }

  /**
   * Get neighbors of a node, including inter-floor connections.
   */
  private getNeighbors(
    nodeId: string,
    mode: RouteMode,
  ): Array<{ neighborId: string; edgeRecord: NormalizedEdgeRecord; edgeWeight: number }> {
    const neighbors: Array<{
      neighborId: string;
      edgeRecord: NormalizedEdgeRecord;
      edgeWeight: number;
    }> = [];

    // Same-floor neighbors via outgoing edges
    const outgoingEdges = this.graph.outgoingEdgesByNodeId.get(nodeId) ?? [];
    for (const edgeRecord of outgoingEdges) {
      if (mode === 'accessible' && !edgeRecord.edge.accessible) {
        // Skip non-accessible edges in accessible mode
        continue;
      }

      const weight = mode === 'accessible' ? edgeRecord.effectiveAccessibleWeight : edgeRecord.edge.standardWeight;

      neighbors.push({
        neighborId: edgeRecord.edge.targetId,
        edgeRecord,
        edgeWeight: weight,
      });

      // Add reverse edge for bidirectional connections
      if (edgeRecord.edge.bidirectional) {
        neighbors.push({
          neighborId: edgeRecord.edge.sourceId,
          edgeRecord,
          edgeWeight: weight,
        });
      }
    }

    // Inter-floor neighbors via connector nodes
    const nodeRecord = this.graph.nodeById.get(nodeId);
    if (nodeRecord) {
      const node = nodeRecord.node;

      // Check for connection to floor above
      if (node.connectsToNodeAboveId && node.connectsToFloorAboveId !== undefined) {
        const aboveNeighborId = node.connectsToNodeAboveId;
        if (this.graph.nodeById.has(aboveNeighborId)) {
          const interFloorWeight = this.interFloorWeight(node.type, 'up', mode);
          const syntheticEdgeRecord: NormalizedEdgeRecord = {
            buildingId: nodeRecord.buildingId,
            floorId: node.floorId,
            edge: {
              id: `interfloor-${nodeId}-${aboveNeighborId}`,
              sourceId: nodeId,
              targetId: aboveNeighborId,
              standardWeight: interFloorWeight,
              accessibleWeight: interFloorWeight,
              accessible: node.type === 'elevator' || node.type === 'ramp',
              bidirectional: true,
            },
            effectiveAccessibleWeight: interFloorWeight,
          };

          neighbors.push({
            neighborId: aboveNeighborId,
            edgeRecord: syntheticEdgeRecord,
            edgeWeight: interFloorWeight,
          });
        }
      }

      // Check for connection to floor below
      if (node.connectsToNodeBelowId && node.connectsToFloorBelowId !== undefined) {
        const belowNeighborId = node.connectsToNodeBelowId;
        if (this.graph.nodeById.has(belowNeighborId)) {
          const interFloorWeight = this.interFloorWeight(node.type, 'down', mode);
          const syntheticEdgeRecord: NormalizedEdgeRecord = {
            buildingId: nodeRecord.buildingId,
            floorId: node.floorId,
            edge: {
              id: `interfloor-${nodeId}-${belowNeighborId}`,
              sourceId: nodeId,
              targetId: belowNeighborId,
              standardWeight: interFloorWeight,
              accessibleWeight: interFloorWeight,
              accessible: node.type === 'elevator' || node.type === 'ramp',
              bidirectional: true,
            },
            effectiveAccessibleWeight: interFloorWeight,
          };

          neighbors.push({
            neighborId: belowNeighborId,
            edgeRecord: syntheticEdgeRecord,
            edgeWeight: interFloorWeight,
          });
        }
      }
    }

    return neighbors;
  }

  /**
   * Calculate weight for inter-floor traversal.
   */
  private interFloorWeight(
    nodeType: string,
    direction: 'up' | 'down',
    mode: RouteMode,
  ): number {
    if (nodeType === 'elevator') {
      return mode === 'accessible' ? INTER_FLOOR_ELEVATOR_WEIGHT : INTER_FLOOR_STANDARD_WEIGHT;
    }
    if (nodeType === 'ramp') {
      return mode === 'accessible' ? INTER_FLOOR_RAMP_WEIGHT : INTER_FLOOR_STANDARD_WEIGHT;
    }
    if (nodeType === 'stairs') {
      return mode === 'accessible' ? INTER_FLOOR_STAIRS_INACCESSIBLE : INTER_FLOOR_STANDARD_WEIGHT;
    }
    // Default fallback
    return mode === 'accessible' ? INTER_FLOOR_STAIRS_INACCESSIBLE : INTER_FLOOR_STANDARD_WEIGHT;
  }

  /**
   * Euclidean heuristic with floor-level penalty.
   * Admissible: never overestimates true cost.
   */
  private heuristic(a: NormalizedNodeRecord, b: NormalizedNodeRecord): number {
    const dx = b.node.x - a.node.x;
    const dy = b.node.y - a.node.y;
    const euclidean = Math.sqrt(dx * dx + dy * dy);
    const floorDiff = Math.abs(b.floorNumber - a.floorNumber);
    return euclidean + floorDiff * FLOOR_PENALTY_PER_LEVEL;
  }
}

import { calculateWeight } from '@shared/pathfinding/graph-builder'
import type { NavEdge, NavFloorGpsBounds, NavNode } from '@shared/types'

/** Default confidence threshold for student-facing GPS rendering. */
export const DEFAULT_MAX_GPS_ACCURACY_METERS = 50

/**
 * Tiny tolerance used to make nearest-node tie handling deterministic.
 * Distances within this epsilon are treated as equivalent and resolved by node ID.
 */
const DISTANCE_TIE_EPSILON = 1e-9

/** Mean Earth radius in meters (IUGG). */
const EARTH_RADIUS_METERS = 6371008.8

export interface NormalizedPoint {
  /** Normalized X coordinate (0 = left edge, 1 = right edge). */
  x: number
  /** Normalized Y coordinate (0 = top edge, 1 = bottom edge). */
  y: number
}

export interface NearestWalkableNodeMatch {
  /** Selected nearest walkable node. */
  node: NavNode
  /** Euclidean distance in normalized map units. */
  distance: number
}

export interface SnapGpsToNodeResult extends NearestWalkableNodeMatch {
  /** Projected normalized point derived from the GPS fix. */
  projectedPoint: NormalizedPoint
}

/**
 * Returns true when floor bounds represent a valid rectangle in GPS space.
 */
export function isGpsBoundsCalibrated(
  bounds: NavFloorGpsBounds | null | undefined,
): bounds is NavFloorGpsBounds {
  if (bounds == null) return false

  return (
    isFiniteNumber(bounds.minLat)
    && isFiniteNumber(bounds.maxLat)
    && isFiniteNumber(bounds.minLng)
    && isFiniteNumber(bounds.maxLng)
    && bounds.minLat < bounds.maxLat
    && bounds.minLng < bounds.maxLng
  )
}

/**
 * Checks whether a latitude/longitude pair is inside configured floor GPS bounds.
 * Bounds are inclusive on every edge.
 */
export function isLatLngWithinBounds(
  latitude: number,
  longitude: number,
  bounds: NavFloorGpsBounds | null | undefined,
): boolean {
  if (!isFiniteNumber(latitude) || !isFiniteNumber(longitude)) return false
  if (!isGpsBoundsCalibrated(bounds)) return false

  return (
    latitude >= bounds.minLat
    && latitude <= bounds.maxLat
    && longitude >= bounds.minLng
    && longitude <= bounds.maxLng
  )
}

/**
 * Projects a GPS coordinate to normalized floor-map coordinates.
 *
 * Projection details:
 * - X grows left → right as longitude grows minLng → maxLng.
 * - Y grows top → bottom, so latitude is inverted (maxLat maps to y=0).
 *
 * Returns null when bounds are missing/invalid or the coordinate is out of bounds.
 */
export function projectLatLngToNormalizedPoint(
  latitude: number,
  longitude: number,
  bounds: NavFloorGpsBounds | null | undefined,
): NormalizedPoint | null {
  if (!isGpsBoundsCalibrated(bounds)) return null
  if (!isLatLngWithinBounds(latitude, longitude, bounds)) return null

  const lngSpan = bounds.maxLng - bounds.minLng
  const latSpan = bounds.maxLat - bounds.minLat

  if (lngSpan <= 0 || latSpan <= 0) return null

  const x = (longitude - bounds.minLng) / lngSpan
  const y = (bounds.maxLat - latitude) / latSpan

  const projected = { x, y }
  return isNormalizedPointInBounds(projected) ? projected : null
}

/**
 * Confidence gate for GPS fixes.
 *
 * Returns true only when the reported accuracy is finite, non-negative, and no
 * worse than `maxAccuracyMeters` (default: 50m).
 */
export function isGpsFixConfident(
  accuracyMeters: number,
  maxAccuracyMeters = DEFAULT_MAX_GPS_ACCURACY_METERS,
): boolean {
  return (
    isFiniteNumber(accuracyMeters)
    && isFiniteNumber(maxAccuracyMeters)
    && accuracyMeters >= 0
    && maxAccuracyMeters >= 0
    && accuracyMeters <= maxAccuracyMeters
  )
}

/**
 * Converts geolocation accuracy in meters to a marker ring radius in map pixels.
 *
 * Uses calibrated floor GPS bounds to estimate horizontal/vertical meter scales,
 * converts both to pixels, and returns their mean so ring size remains stable
 * across non-square maps.
 */
export function accuracyMetersToMapPixelRadius(
  accuracyMeters: number,
  bounds: NavFloorGpsBounds | null | undefined,
  mapWidthPx: number,
  mapHeightPx: number,
): number {
  if (!isFiniteNumber(accuracyMeters) || accuracyMeters <= 0) return 0
  if (!isFiniteNumber(mapWidthPx) || mapWidthPx <= 0) return 0
  if (!isFiniteNumber(mapHeightPx) || mapHeightPx <= 0) return 0

  const floorScale = deriveFloorScaleMeters(bounds)
  if (floorScale == null) return 0

  const xPixels = (accuracyMeters / floorScale.widthMeters) * mapWidthPx
  const yPixels = (accuracyMeters / floorScale.heightMeters) * mapHeightPx

  if (!isFiniteNumber(xPixels) || !isFiniteNumber(yPixels)) return 0

  return (xPixels + yPixels) / 2
}

/**
 * Finds the nearest walkable node to a normalized point.
 *
 * Candidate nodes are constrained to IDs that participate in at least one
 * floor-scoped edge with a finite standard weight, which keeps snapping aligned
 * with graph connectivity.
 */
export function findNearestWalkableNode(
  point: NormalizedPoint,
  nodes: readonly NavNode[],
  edges: readonly NavEdge[],
): NearestWalkableNodeMatch | null {
  if (!isNormalizedPointInBounds(point)) return null

  const walkableNodeIds = deriveWalkableNodeIds(nodes, edges)
  if (walkableNodeIds.size === 0) return null

  let bestMatch: NearestWalkableNodeMatch | null = null

  for (const node of nodes) {
    if (!walkableNodeIds.has(node.id)) continue

    const distance = calculateWeight(point.x, point.y, node.x, node.y)

    if (bestMatch == null) {
      bestMatch = { node, distance }
      continue
    }

    if (distance < bestMatch.distance - DISTANCE_TIE_EPSILON) {
      bestMatch = { node, distance }
      continue
    }

    if (
      Math.abs(distance - bestMatch.distance) <= DISTANCE_TIE_EPSILON
      && node.id.localeCompare(bestMatch.node.id) < 0
    ) {
      bestMatch = { node, distance }
    }
  }

  return bestMatch
}

/**
 * Convenience helper: projects GPS to normalized map space and snaps it to the
 * nearest walkable node on the floor.
 */
export function snapLatLngToNearestWalkableNode(
  latitude: number,
  longitude: number,
  bounds: NavFloorGpsBounds | null | undefined,
  nodes: readonly NavNode[],
  edges: readonly NavEdge[],
): SnapGpsToNodeResult | null {
  const projectedPoint = projectLatLngToNormalizedPoint(latitude, longitude, bounds)
  if (projectedPoint == null) return null

  const nearest = findNearestWalkableNode(projectedPoint, nodes, edges)
  if (nearest == null) return null

  return {
    ...nearest,
    projectedPoint,
  }
}

/**
 * Determines whether a normalized point is inside map bounds [0,1] x [0,1].
 */
export function isNormalizedPointInBounds(point: NormalizedPoint): boolean {
  return (
    isFiniteNumber(point.x)
    && isFiniteNumber(point.y)
    && point.x >= 0
    && point.x <= 1
    && point.y >= 0
    && point.y <= 1
  )
}

function deriveWalkableNodeIds(nodes: readonly NavNode[], edges: readonly NavEdge[]): Set<string> {
  const knownNodeIds = new Set(nodes.map((node) => node.id))
  const walkable = new Set<string>()

  for (const edge of edges) {
    if (!isFiniteNumber(edge.standardWeight)) continue

    if (knownNodeIds.has(edge.sourceId)) walkable.add(edge.sourceId)
    if (knownNodeIds.has(edge.targetId)) walkable.add(edge.targetId)
  }

  return walkable
}

function deriveFloorScaleMeters(
  bounds: NavFloorGpsBounds | null | undefined,
): { widthMeters: number; heightMeters: number } | null {
  if (!isGpsBoundsCalibrated(bounds)) return null

  const midLat = (bounds.minLat + bounds.maxLat) / 2
  const midLng = (bounds.minLng + bounds.maxLng) / 2

  const widthMeters = haversineDistanceMeters(midLat, bounds.minLng, midLat, bounds.maxLng)
  const heightMeters = haversineDistanceMeters(bounds.minLat, midLng, bounds.maxLat, midLng)

  if (!isFiniteNumber(widthMeters) || widthMeters <= 0) return null
  if (!isFiniteNumber(heightMeters) || heightMeters <= 0) return null

  return { widthMeters, heightMeters }
}

function haversineDistanceMeters(
  lat1: number,
  lng1: number,
  lat2: number,
  lng2: number,
): number {
  const lat1Rad = degreesToRadians(lat1)
  const lat2Rad = degreesToRadians(lat2)
  const dLat = degreesToRadians(lat2 - lat1)
  const dLng = degreesToRadians(lng2 - lng1)

  const sinDLat = Math.sin(dLat / 2)
  const sinDLng = Math.sin(dLng / 2)

  const a =
    sinDLat * sinDLat
    + Math.cos(lat1Rad) * Math.cos(lat2Rad) * sinDLng * sinDLng

  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a))
  return EARTH_RADIUS_METERS * c
}

function degreesToRadians(value: number): number {
  return (value * Math.PI) / 180
}

function isFiniteNumber(value: unknown): value is number {
  return typeof value === 'number' && Number.isFinite(value)
}

/**
 * Route session state machine — pure computation, no React dependencies.
 *
 * Coordinates pathfinding (T01 engine) and direction generation (T01)
 * into a single discriminated union state that drives the UI.
 */

import type { NavNode } from '../../src/shared/types';
import type {
  DirectionsResult,
  NormalizedNavGraph,
  PathResult,
  RouteMode,
} from '../domain/navGraph';
import { MobilePathfindingEngine } from './pathfindingEngine';
import { generateDirections } from './generateDirections';

// ============================================================
// Phase types
// ============================================================

export type RouteSessionPhase =
  | 'idle'
  | 'computing'
  | 'ready'
  | 'no-route'
  | 'error';

// ============================================================
// Discriminated union state types
// ============================================================

export interface RouteSessionIdleState {
  readonly phase: 'idle';
  readonly start: NavNode | null;
  readonly destination: NavNode | null;
  readonly routeMode: RouteMode;
  readonly path: null;
  readonly directions: null;
  readonly errorMessage: null;
}

export interface RouteSessionComputingState {
  readonly phase: 'computing';
  readonly start: NavNode | null;
  readonly destination: NavNode | null;
  readonly routeMode: RouteMode;
  readonly path: null;
  readonly directions: null;
  readonly errorMessage: null;
}

export interface RouteSessionReadyState {
  readonly phase: 'ready';
  readonly start: NavNode | null;
  readonly destination: NavNode | null;
  readonly routeMode: RouteMode;
  readonly path: PathResult;
  readonly directions: DirectionsResult;
  readonly errorMessage: null;
}

export interface RouteSessionNoRouteState {
  readonly phase: 'no-route';
  readonly start: NavNode | null;
  readonly destination: NavNode | null;
  readonly routeMode: RouteMode;
  readonly path: null;
  readonly directions: null;
  readonly errorMessage: null;
}

export interface RouteSessionErrorState {
  readonly phase: 'error';
  readonly start: NavNode | null;
  readonly destination: NavNode | null;
  readonly routeMode: RouteMode;
  readonly path: null;
  readonly directions: null;
  readonly errorMessage: string;
}

/**
 * Discriminated union of all route session states.
 *
 * Discriminant key: `phase`
 *
 * Phase meanings:
 * - `idle`:    No start/destination yet
 * - `computing`: Currently computing (sync, so only an intermediate phase)
 * - `ready`:  Route found — path and directions available
 * - `no-route`: Start & dest selected but no path exists
 * - `error`:  Node not present in graph or other error
 */
export type RouteSessionState =
  | RouteSessionIdleState
  | RouteSessionComputingState
  | RouteSessionReadyState
  | RouteSessionNoRouteState
  | RouteSessionErrorState;

// ============================================================
// Options
// ============================================================

export interface RouteSessionOptions {
  readonly graph: NormalizedNavGraph;
  readonly mode: RouteMode;
  readonly start: NavNode | null;
  readonly destination: NavNode | null;
}

// ============================================================
// Private helpers
// ============================================================

/**
 * Compute directions from a found path result.
 * Uses nodeMap and floorMap from the normalized graph.
 */
function computeDirections(
  path: PathResult,
  mode: RouteMode,
  graph: NormalizedNavGraph,
): DirectionsResult {
  // Extract plain NavNode objects from normalized records
  const nodeMap = new Map<string, NavNode>();
  for (const [id, record] of graph.nodeById) {
    nodeMap.set(id, record.node);
  }

  // Extract plain NavFloor objects from normalized records
  const floorMap = new Map<number, import('../../src/shared/types').NavFloor>();
  for (const [id, record] of graph.floorById) {
    floorMap.set(id, record.floor);
  }

  return generateDirections(
    path.nodeIds,
    nodeMap,
    mode,
    floorMap,
  );
}

// ============================================================
// Main computation function
// ============================================================

/**
 * Compute a route session state synchronously.
 *
 * A* is fast enough that no async boundary is needed.
 * The 'computing' phase is included for UI tooling (DevTools)
 * and to make the phase model complete.
 *
 * Transitions:
 * - start === null || destination === null → 'idle'
 * - start/dest valid but not in graph         → 'error'
 * - start/dest in graph, no path found        → 'no-route'
 * - start/dest in graph, path found           → 'ready'
 */
export function computeRouteSession(options: RouteSessionOptions): RouteSessionState {
  const { graph, mode, start, destination } = options;

  // Guard: missing input
  if (start === null || destination === null) {
    return {
      phase: 'idle',
      start,
      destination,
      routeMode: mode,
      path: null,
      directions: null,
      errorMessage: null,
    };
  }

  // Guard: nodes not in graph
  if (!graph.nodeById.has(start.id) || !graph.nodeById.has(destination.id)) {
    return {
      phase: 'error',
      start,
      destination,
      routeMode: mode,
      path: null,
      directions: null,
      errorMessage: 'One or both selected nodes are not present in the navigation graph.',
    };
  }

  // Guard: start === destination
  if (start.id === destination.id) {
    return {
      phase: 'idle',
      start,
      destination,
      routeMode: mode,
      path: null,
      directions: null,
      errorMessage: null,
    };
  }

  // Compute path
  const engine = new MobilePathfindingEngine(graph);
  const path = engine.findRoute(start.id, destination.id, mode);

  if (!path.found) {
    return {
      phase: 'no-route',
      start,
      destination,
      routeMode: mode,
      path: null,
      directions: null,
      errorMessage: null,
    };
  }

  // Compute directions
  const directions = computeDirections(path, mode, graph);

  return {
    phase: 'ready',
    start,
    destination,
    routeMode: mode,
    path,
    directions,
    errorMessage: null,
  };
}

